<?php function reportBars(array $rows): string { if(!$rows)return '<div class="empty-inline">No records for this filter.</div>';$max=max(1,...array_map(fn($r)=>(int)$r['total'],$rows));ob_start();foreach($rows as $r){$w=max(3,((int)$r['total']/$max)*100);echo '<div class="report-bar"><span>'.e(ucwords(str_replace('_',' ',$r['label']))).'</span><div><i style="--bar:'.$w.'%"></i></div><b>'.e($r['total']).'</b></div>';}return ob_get_clean();} $query=http_build_query(array_filter(['cycle'=>$cycle,'program'=>$program])); ?>
<div class="page-heading admin-heading"><div><span class="eyebrow">Operational intelligence</span><h1>Admissions reports</h1><p>Live funnel, applicant profile, payments, seats, geography and team workload.</p></div><div class="heading-actions"><a class="button button-primary" href="<?= url('admin/applications/export'.($query?'?'.$query:'')) ?>">↓ Export filtered source data</a></div></div>
<form class="card table-filters" method="get" action="<?= url('admin/reports') ?>"><select name="cycle"><option value="">All cycles</option><?php foreach($cycles as $item):?><option value="<?= e($item['id']) ?>"<?= selected($cycle,$item['id']) ?>><?= e($item['name']) ?></option><?php endforeach?></select><select name="program"><option value="">All programmes</option><?php foreach($programs as $item):?><option value="<?= e($item['id']) ?>"<?= selected($program,$item['id']) ?>><?= e($item['name'].' · '.$item['code']) ?></option><?php endforeach?></select><button class="button button-primary button-sm">Apply report filter</button><?php if($cycle||$program):?><a href="<?= url('admin/reports') ?>">Clear</a><?php endif?></form>
<div class="admin-stat-grid"><article><div class="stat-icon teal">▤</div><div><span>Applications</span><b><?= number_format($totals['applications']) ?></b><small>Filtered records</small></div></article><article><div class="stat-icon gold">↗</div><div><span>Submitted</span><b><?= number_format($totals['submitted']) ?></b><small>Final submissions</small></div></article><article><div class="stat-icon green">✓</div><div><span>Admitted</span><b><?= number_format($totals['admitted']) ?></b><small>Confirmed admissions</small></div></article><article><div class="stat-icon teal">₹</div><div><span>Verified payments</span><b><?= money($totals['verified_revenue']) ?></b><small>Application and admission fees</small></div></article></div>
<div class="report-notice"><span>i</span><p>Reports reflect current database records and selected filters. Small category groups may require privacy suppression before external sharing.</p></div><div class="report-grid"><section class="card report-card"><div class="card-heading"><div><span class="eyebrow">Funnel</span><h2>Applications by status</h2></div></div><?= reportBars($status) ?></section><section class="card report-card"><div class="card-heading"><div><span class="eyebrow">Reservation view</span><h2>Applicant category</h2></div></div><?= reportBars($category) ?></section><section class="card report-card"><div class="card-heading"><div><span class="eyebrow">Profile</span><h2>Gender distribution</h2></div></div><?= reportBars($gender) ?></section><section class="card report-card"><div class="card-heading"><div><span class="eyebrow">Geography</span><h2>Top applicant states</h2></div></div><?= reportBars($geography) ?></section><section class="card report-card"><div class="card-heading"><div><span class="eyebrow">Team capacity</span><h2>Reviewer workload</h2></div></div><?= reportBars($reviewers) ?></section><section class="card report-card"><div class="card-heading"><div><span class="eyebrow">Recent pace</span><h2>Daily submissions</h2></div></div><?= $daily?reportBars(array_reverse($daily)):'<div class="empty-inline">No submitted applications yet.</div>' ?></section></div>
<section class="card application-table-card"><div class="card-heading"><div><span class="eyebrow">Finance</span><h2>Payment report</h2></div></div><div class="table-wrap"><table><thead><tr><th>Fee type</th><th>Status</th><th>Records</th><th>Amount</th></tr></thead><tbody><?php foreach($payments as $row):?><tr><td><?= e(ucwords(str_replace('_',' ',$row['type']))) ?></td><td><span class="status-pill status-<?= e($row['status']) ?>"><?= e(ucfirst($row['status'])) ?></span></td><td><?= number_format((int)$row['records']) ?></td><td><?= money($row['amount']) ?></td></tr><?php endforeach?></tbody></table></div></section>
<section class="card application-table-card"><div class="card-heading"><div><span class="eyebrow">Capacity control</span><h2>Seat position</h2></div></div><div class="table-wrap"><table><thead><tr><th>Cycle</th><th>Programme</th><th>Category</th><th>Quota</th><th>Capacity</th><th>Allocated</th><th>Available</th></tr></thead><tbody><?php foreach($seats as $row):?><tr><td><?= e($row['cycle_name']) ?></td><td><b><?= e($row['program_name']) ?></b></td><td><?= e($row['category']) ?></td><td><?= e($row['quota']) ?></td><td><?= number_format((int)$row['seats']) ?></td><td><?= number_format((int)$row['filled_seats']) ?></td><td><b><?= number_format((int)$row['available']) ?></b></td></tr><?php endforeach?></tbody></table></div></section>
